import dataclasses

import models


def _get_run_class():
    """Find the cron run record class by its distinguishing fields."""
    for name in dir(models):
        obj = getattr(models, name)
        if isinstance(obj, type) and dataclasses.is_dataclass(obj):
            try:
                field_names = {f.name for f in dataclasses.fields(obj)}
            except TypeError:
                continue
            if "run_id" in field_names and "wake_at_iso" in field_names:
                return obj
    raise RuntimeError("Could not find cron run class with run_id and wake_at_iso fields")


def _make_run(**kwargs):
    cls = _get_run_class()
    defaults = {
        "run_id": "run-1",
        "job_id": "job-1",
        "wake_at_iso": "2024-01-01T00:00:00+00:00",
        "push_at_iso": "2024-01-01T00:05:00+00:00",
    }
    defaults.update(kwargs)
    return cls(**defaults)


def test_run_basic_fields():
    """Case that already worked: basic field access on a run record."""
    run = _make_run()
    assert run.run_id == "run-1"
    assert run.job_id == "job-1"
    assert run.status == "pending"
    assert run.placeholder_sent is False
    assert run.pushed_final is False
